// Generated by the launcher; regenerated on every launch.
export default {
  id: "numes",
  setup: async (context) => {
    const { e2eeProviderIds, e2eeStatePath } = context.options ?? {};
    
  const encrypted = new Set();
  let durable = Promise.resolve();
  async function marked(sessionID) {
    if (encrypted.has(sessionID)) return true;
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(sessionID)) throw new Error("Invalid encrypted session identity");
    const fs = await import("node:fs/promises");
    try {
      const stat = await fs.stat(e2eeStatePath + "/" + sessionID);
      if (!stat.isFile() || stat.size !== 0) throw new Error("Invalid encrypted session marker");
      encrypted.add(sessionID);
      return true;
    } catch (error) {
      if (error.code === "ENOENT") return false;
      throw new Error("Cannot read encrypted session protection state");
    }
  }
  async function protect(sessionID) {
    if (await marked(sessionID)) return;
    durable = durable.then(async () => {
      const fs = await import("node:fs/promises");
      await fs.mkdir(e2eeStatePath, { recursive: true, mode: 0o700 });
      try { await fs.writeFile(e2eeStatePath + "/" + sessionID, "", { mode: 0o600, flag: "wx" }); }
      catch (error) { if (error.code !== "EEXIST") throw error; }
    });
    await durable;
    encrypted.add(sessionID);
  }

    const allowed = new Map();
    const syntheticMock = /^synthetic\/e2ee-mock-v1(?=:|$)/;
    function requireProtection() {
      if (!Array.isArray(e2eeProviderIds) || e2eeProviderIds.length === 0 ||
          !e2eeProviderIds.every((id) => typeof id === "string" && id) ||
          typeof e2eeStatePath !== "string" || !e2eeStatePath ||
          typeof context.session?.get !== "function" ||
          typeof context.session?.context !== "function" ||
          typeof context.agent?.list !== "function" ||
          typeof context.model?.list !== "function" ||
          typeof context.model?.default !== "function") {
        throw new Error("OpenCode cannot enforce encrypted history protection: session APIs and durable state are required");
      }
    }
    function encryptedProvider(model) {
      return e2eeProviderIds.includes(model?.providerID) && !syntheticMock.test(model?.id ?? "");
    }
    function encryptedMessage(message) {
      const model = message?.model;
      return !syntheticMock.test(model?.id ?? "") &&
        (e2eeProviderIds.includes(model?.providerID) || /:e2ee(?=:|$)/.test(model?.id ?? ""));
    }
    async function session(sessionID) {
      const info = await context.session.get({ sessionID });
      if (!info || info.id !== sessionID) throw new Error("Cannot verify encrypted session ancestry");
      return info;
    }
    // Match OpenCode 2's session -> available agent model -> default order.
    // Defaults need not have been copied into a newly created session yet.
    async function selectedModel(info) {
      if (info.model) return info.model;
      const { data: agents } = await context.agent.list();
      if (!Array.isArray(agents)) throw new Error("Cannot verify encrypted session model");
      const agent = info.agent ? agents.find((item) => item.id === info.agent) : agents[0];
      if (!agent) throw new Error("Cannot verify encrypted session model");
      let preferred;
      if (agent.model) {
        const { data: models } = await context.model.list();
        if (!Array.isArray(models)) throw new Error("Cannot verify encrypted session model");
        preferred = models.find((model) => model.providerID === agent.model.providerID && model.id === agent.model.id);
      }
      const model = preferred?.enabled ? preferred : (await context.model.default())?.data;
      if (!model || typeof model.providerID !== "string" || typeof model.id !== "string")
        throw new Error("Cannot verify encrypted session model");
      return model;
    }
    // Output flows to the parent only; a fork also carries its source's history.
    async function lineage(sessionID, includeForks) {
      const found = [];
      const pending = [sessionID];
      while (pending.length > 0) {
        const current = pending.shift();
        if (found.some((info) => info.id === current)) continue;
        if (found.length >= 64) throw new Error("Cannot verify encrypted session ancestry");
        const info = await session(current);
        found.push(info);
        if (info.parentID) pending.push(info.parentID);
        if (includeForks && info.fork?.sessionID) pending.push(info.fork.sessionID);
      }
      return found;
    }
    async function protectedHistory(sessionID) {
      for (const info of await lineage(sessionID, true)) {
        const current = info.id;
        if (await marked(current)) return true;
        // Titles can run before the first encrypted primary request. A fresh
        // user message has no model metadata, so also honor the selection.
        if (encryptedMessage({ model: await selectedModel(info) })) {
          await protect(current);
          return true;
        }
        const messages = await context.session.context({ sessionID: current });
        if (!Array.isArray(messages)) throw new Error("Cannot verify encrypted session history");
        if (messages.some(encryptedMessage)) {
          await protect(current);
          return true;
        }
      }
      return false;
    }
    async function guard({ sessionID, model, kind }) {
      requireProtection();
      if (!sessionID) throw new Error("Encrypted inference requires a session identity");
      await durable;
      if (encryptedProvider(model)) {
        for (const info of await lineage(sessionID, false)) {
          await protect(info.id);
          allowed.delete(info.id);
        }
        return;
      }
      if (!await protectedHistory(sessionID)) return;
      const target = model.providerID + "/" + model.id;
      const permission = allowed.get(sessionID);
      if (permission === target) return;
      if (permission === "next" && kind === "primary") {
        allowed.set(sessionID, target);
        return;
      }
      throw new Error("This session contains E2EE history. Select an attested E2EE model, or explicitly run /allow-unencrypted-history to let the selected regular or synthetic provider read the history.");
    }
    await context.session.hook("model.request", guard);
    await context.command.transform((editor) => {
      editor.add({
        name: "allow-unencrypted-history",
        description: "Allow this E2EE history to be sent to the selected regular model",
        execute: async (input) => {
          requireProtection();
          allowed.set(input.sessionID, "next");
          await context.session.prompt({
            ...input.prompt,
            sessionID: input.sessionID,
            text: "I explicitly allow this conversation history to be sent to the selected regular model without end-to-end encryption. Continue.",
            delivery: input.delivery,
          });
        },
      });
    });
  },
};
